package pe.nexo.store.product;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController@RequestMapping("/api/products")public class ProductController{private final ProductService service;public ProductController(ProductService service){this.service=service;}@GetMapping public List<Product>findAll(@RequestParam(required=false)String category){return service.findAll(category);}@GetMapping("/offers")public List<Product>offers(){return service.findOffers();}@GetMapping("/{id}/related")public List<Product>related(@PathVariable Long id){Product p=service.findById(id);return service.findAll(p.getCategory()).stream().filter(x->!x.getId().equals(id)).limit(4).toList();}@GetMapping("/{id}")public Product findOne(@PathVariable Long id){return service.findById(id);}}
